test('production KNX GA ownership and registration', (context) => {
  const root = path.resolve(__dirname, '..');
  const source = fs.readFileSync(path.join(root, 'usermods/KNX_IP/usermod_knx_ip.cpp'), 'utf8').replace(/\r\n/g, '\n');
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'wled-ga-'));
  try {
    const extract = (startMarker, endMarker) => {
      const start = source.indexOf(startMarker);
      const end = source.indexOf(endMarker, start);
      assert.ok(start >= 0 && end > start, `Missing production region: ${startMarker}`);
      return source.slice(start, end);
    };
    const parsing = extract('static bool parseAddressComponent(', '/**\n * Test the GA conflict detection system');
    const registration = extract('void KnxIpUsermod::clearSegmentKOs(', '#ifdef UNIT_TEST');
    const notification = extract('void KnxIpUsermod::checkGAConflictsAndNotifyGUI(', '/**\n * Run all GA conflict tests');
    const config = extract('bool KnxIpUsermod::readFromConfig(', 'void KnxIpUsermod::addToJsonInfo(');
    const hash = extract('uint32_t KnxIpUsermod::computeGATableHash(', '// WLED core globals');
    const loop = extract('void KnxIpUsermod::retryKnxStart()', 'unsigned long now = millis();') + '}\n';
    fs.writeFileSync(path.join(directory, 'production_ga.inc'), parsing + registration + notification + hash + config + loop);
    const executable = path.join(directory, process.platform === 'win32' ? 'ga-test.exe' : 'ga-test');
    const compiler = (process.env.CXX || 'c++').match(/(?:[^\s"]+|"[^"]*")+/g).map(part => part.replace(/^"|"$/g, ''));
    if (spawnSync(compiler[0], [...compiler.slice(1), '--version']).error?.code === 'ENOENT') {
      context.skip('Set CXX to a host C++17 compiler (also accepts zig c++).');
      return;
    }
    const result = spawnSync(compiler[0], [...compiler.slice(1), '-std=c++17', '-Wall', '-Wextra', '-Werror', '-Wno-unused-function', '-Wno-unused-parameter', '-DKNX_UM_SUPPRESS_WARN', '-DKNX_GA_PRODUCTION_HEADER="production_ga.inc"', '-I', path.join(root, 'test/knx_control/stubs'), '-I', directory, path.join(root, 'test/knx_control/ga_test.cpp'), '-o', executable], { encoding: 'utf8' });
    assert.ifError(result.error);
    assert.equal(result.status, 0, result.stdout + result.stderr);
    const run = spawnSync(executable, [], { encoding: 'utf8' });
    assert.ifError(run.error);
    console.log(run.stdout);
    assert.equal(run.status, 0, run.stdout + run.stderr);
  } finally {
    fs.rmSync(directory, { recursive: true, force: true });
  }
});

test('production UI shows KNX error 89 and clears its Info state', () => {
  const source = fs.readFileSync(path.join(__dirname, '../wled00/data/index.js'), 'utf8');
  const branch = source.slice(source.indexOf('if (s.error && s.error != 0)'), source.indexOf('selectedPal = i.pal;', source.indexOf('if (s.error && s.error != 0)')));
  const toasts = [];
  let refreshes = 0;
  const context = vm.createContext({ s: { error: 89 }, currentError: null, currentErrorMsg: '', isInfo: true, lastinfo: {}, showToast: message => toasts.push(message), populateInfo: () => { ++refreshes; } });
  vm.runInContext(branch, context);
  assert.equal(context.currentError, 89);
  assert.match(context.currentErrorMsg, /KNX Group Address conflict/);
  assert.doesNotMatch(toasts[0], /memory|RAM/i);
  context.s = { error: 89, error_msg: 'KNX GA conflicts: 5/0/1' };
  vm.runInContext(branch, context);
  assert.match(context.currentErrorMsg, /5\/0\/1/);
  context.s = {};
  vm.runInContext(branch, context);
  assert.equal(context.currentError, null);
  assert.equal(context.currentErrorMsg, '');
  assert.equal(refreshes, 3);
});
